import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"入门路线","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1788308924000}'),i={name:"guide/getting-started.md"};function o(n,a,s,h,d,m){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="入门路线" tabindex="-1">入门路线 <a class="header-anchor" href="#入门路线" aria-label="Permalink to &quot;入门路线&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 本站按“建立 AI 概念、理解 LLM 原理、AI 绘画专题、动手实践、积累资料”五个阶段组织；零基础读者建议按顺序走完整路线，有明确目标的读者可以按背景跳读。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>本页是全站路线图，可以直接从这一页开始，不要求先读任何其他页面。</li><li>不要求编程经验，也不要求数学基础；各页涉及的新术语都会先解释。</li><li>一个边界：本页只给路线和取舍建议，不替代各页正文，具体概念以对应页面为准。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>说出本站五个阶段各自回答什么问题。</li><li>根据自己的背景选择一条主线，并说明哪些页面可以暂时跳过。</li><li>安排第一周的具体学习任务，并知道要产出什么笔记。</li><li>判断每条路线走完时自己应该留下什么产出。</li><li>遇到陌生概念时，判断它大概能在哪一页找到解释。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="整体路线分为哪几个阶段" tabindex="-1">整体路线分为哪几个阶段 <a class="header-anchor" href="#整体路线分为哪几个阶段" aria-label="Permalink to &quot;整体路线分为哪几个阶段&quot;">​</a></h3><p>本站全部页面可以分成五个阶段，每个阶段解决一类问题：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>建立概念（AI 基础） -&gt; 理解模型（LLM 理论） -&gt; 专题深入（AI 绘画） -&gt; 动手实践（Prompt 与工具） -&gt; 持续积累（资料与术语表）</span></span></code></pre></div><p>五个阶段的顺序反映的是依赖关系：后面的阶段会反复使用前面的概念。不理解 Token 和上下文，就很难判断一段提示词为什么失效；不理解训练和推理的区别，就容易把采样参数当成知识开关。</p><ul><li><strong>阶段一：建立概念。</strong> <a href="/ai/basics">AI 基础概念</a>、<a href="/ai/machine-learning">机器学习入门</a>、<a href="/ai/neural-networks">神经网络直觉</a>。目标不是推导公式，而是知道模型怎样从数据中调整参数，以及为什么训练表现不等于真实表现。 <ul><li>解决的问题：模型和“写死规则的程序”差在哪，参数、损失、泛化这些词在说什么。</li><li>顺带澄清的误解：“AI 会像人一样思考”“训练时的表现就是真实效果”。</li></ul></li><li><strong>阶段二：理解 LLM 理论。</strong> <a href="/llm/basics">大模型入门</a>、<a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a>、<a href="/llm/transformer">Transformer 直觉</a>、<a href="/llm/inference-decoding">推理与解码</a>、<a href="/llm/training-alignment">训练、微调与对齐</a>、<a href="/llm/rag-agent">RAG 与 Agent</a>。目标是能说明“文本表示、模型计算、解码选择、内部能力、外部资料与工具调用”各自负责什么。 <ul><li>解决的问题：一段文字如何变成 Token，模型如何利用上下文，回答是怎么逐词生成的。</li><li>顺带澄清的误解：“联网了就一定准确”“调高采样参数能提升智力”。</li></ul></li><li><strong>阶段三：AI 绘画专题。</strong> <a href="/concepts/base-model">底模是什么</a>、<a href="/concepts/components">AI 绘画由哪些部分组成</a>、<a href="/concepts/how-it-works">基本原理</a>、<a href="/models/ecosystems">常见模型生态</a>、<a href="/lora/basics">LoRA 入门</a>。目标是看懂一张工作流图在做什么，先跑通最小文生图流程，再逐步加入 LoRA、ControlNet、局部重绘和放大。 <ul><li>解决的问题：底模、LoRA、工作流各自决定画面的哪一部分，出图失败该先查哪里。</li><li>顺带澄清的误解：“换更新的底模就能解决所有问题”“一个 LoRA 能覆盖所有风格”。</li></ul></li><li><strong>阶段四：动手实践。</strong> <a href="/prompting/basics">Prompt 入门</a>、<a href="/workflows/workflow-vs-template">工作流和模板区别</a>、<a href="/tools/common-tools">常用工具</a>。目标是把任务写清楚，并区分工具界面与模型能力。 <ul><li>解决的问题：为什么同一个模型在不同工具里表现不同，一份完整的任务说明长什么样。</li><li>顺带澄清的误解：“存在万能 Prompt 模板”“工具界面好看就代表模型更强”。</li></ul></li><li><strong>阶段五：持续积累。</strong> <a href="/resources/websites">常用网站</a>、<a href="/resources/tutorials">精选教程</a>、<a href="/glossary">术语表</a>。目标是建立自己的资料体系：记录来源与版本、模型卡与许可证、有效 Prompt 与失败案例。 <ul><li>解决的问题：教程和模型更新很快，怎样让学过的东西可以复用、可以追溯。</li><li>顺带澄清的误解：“收藏了链接就等于学会了”。</li></ul></li></ul><p>以上页面标题、链接和顺序与侧边栏一致，就是推荐的阅读顺序；个别页面之间的依赖关系，还会在该页开头的前置知识里再次说明。</p><h3 id="为什么先概念后工具" tabindex="-1">为什么先概念后工具 <a class="header-anchor" href="#为什么先概念后工具" aria-label="Permalink to &quot;为什么先概念后工具&quot;">​</a></h3><p>工具界面可能每隔几个月就大改，概念却相对稳定。先理解 Token、上下文、幻觉这些概念，再学 Prompt 和工作流，遇到新工具时能自己判断“这个选项大概在改什么”；反过来，先堆工具和技巧，往往只能背模板，换一个任务或工具就失效。</p><h3 id="每个阶段读到什么程度就可以继续" tabindex="-1">每个阶段读到什么程度就可以继续 <a class="header-anchor" href="#每个阶段读到什么程度就可以继续" aria-label="Permalink to &quot;每个阶段读到什么程度就可以继续&quot;">​</a></h3><ul><li>阶段一：能区分 AI、机器学习、深度学习和模型，能解释什么是过拟合与泛化就够了，不必会推导反向传播。</li><li>阶段二：能说清一段文字如何变成 Token、模型如何利用上下文、生成时采样参数改变了什么就够了。</li><li>阶段三：能跑通一次文生图，并说出工作流里主要节点各负责什么。</li><li>阶段四：能独立写出一个包含任务、上下文、输出格式、约束的 Prompt，并知道角色与示例这两个进阶要素什么时候用。</li><li>阶段五：只需要建立习惯，遇到问题时知道回哪里查。</li></ul><h3 id="遇到某个词-该回哪一页查" tabindex="-1">遇到某个词，该回哪一页查 <a class="header-anchor" href="#遇到某个词-该回哪一页查" aria-label="Permalink to &quot;遇到某个词，该回哪一页查&quot;">​</a></h3><p><a href="/glossary">术语表</a>是全部术语的总索引；此外，常见词大致落在这些页面，忘了直接回去翻对应章节即可：</p><ul><li>Token、上下文窗口、幻觉：<a href="/llm/basics">大模型入门</a>。</li><li>Embedding、向量、子词切分：<a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a>。</li><li>Attention、上下文表示：<a href="/llm/transformer">Transformer 直觉</a>。</li><li>Temperature、Top-p、KV Cache、自回归：<a href="/llm/inference-decoding">推理与解码</a>。</li><li>预训练、微调、对齐：<a href="/llm/training-alignment">训练、微调与对齐</a>。</li><li>检索增强、工具调用、Agent：<a href="/llm/rag-agent">RAG 与 Agent</a>。</li><li>底模、Checkpoint：<a href="/concepts/base-model">底模是什么</a>。</li><li>LoRA、触发词：<a href="/lora/basics">LoRA 入门</a>。</li><li>工作流、模板：<a href="/workflows/workflow-vs-template">工作流和模板区别</a>。</li><li>过拟合、泛化、评估指标：<a href="/ai/machine-learning">机器学习入门</a>。</li><li>权重、激活函数、反向传播：<a href="/ai/neural-networks">神经网络直觉</a>。</li></ul><h2 id="按目标选路线" tabindex="-1">按目标选路线 <a class="header-anchor" href="#按目标选路线" aria-label="Permalink to &quot;按目标选路线&quot;">​</a></h2><p>五阶段是默认顺序；如果目标已经明确，也可以直接按下面四条路线走。每条路线都列出了推荐阅读顺序、可以暂时跳过的页面和走完时最该记住的东西：</p><table tabindex="0"><thead><tr><th>目标</th><th>推荐路线（按顺序）</th><th>可以先跳过</th><th>重点记住</th></tr></thead><tbody><tr><td>快速用上对话 AI</td><td><a href="/ai/basics">AI 基础概念</a> → <a href="/llm/basics">大模型入门</a> → <a href="/prompting/basics">Prompt 入门</a> → <a href="/tools/common-tools">常用工具</a></td><td>数学与架构细节页（神经网络、Transformer 的推导部分）</td><td>Token、上下文窗口、幻觉</td></tr><tr><td>搞懂大模型原理</td><td><a href="/ai/machine-learning">机器学习入门</a> → <a href="/ai/neural-networks">神经网络直觉</a> → <a href="/llm/basics">大模型入门</a> → <a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a> → <a href="/llm/transformer">Transformer 直觉</a> → <a href="/llm/inference-decoding">推理与解码</a> → <a href="/llm/training-alignment">训练、微调与对齐</a></td><td>AI 绘画与动手实践页</td><td>预测下一个词、注意力、训练三阶段</td></tr><tr><td>画 AI 插画</td><td><a href="/ai/basics">AI 基础概念</a> → <a href="/concepts/base-model">底模是什么</a> → <a href="/concepts/components">AI 绘画由哪些部分组成</a> → <a href="/concepts/how-it-works">基本原理</a> → <a href="/models/ecosystems">常见模型生态</a> → <a href="/lora/basics">LoRA 入门</a> → <a href="/prompting/basics">Prompt 入门</a></td><td>LLM 理论页（微调概念读 <a href="/llm/training-alignment">训练、微调与对齐</a> 回补即可）</td><td>底模、采样器与步数、LoRA 兼容性</td></tr><tr><td>写好 Prompt</td><td><a href="/prompting/basics">Prompt 入门</a> → <a href="/llm/basics">大模型入门</a> → <a href="/workflows/workflow-vs-template">工作流和模板区别</a> → <a href="/llm/rag-agent">RAG 与 Agent</a></td><td>神经网络与架构页</td><td>六要素、负向约束的局限、迭代改进</td></tr></tbody></table><p>所有路线都默认先过一遍 <a href="/ai/basics">AI 基础概念</a>；途中术语卡住，就回 <a href="/glossary">术语表</a> 查。路线只是入口，走完一条后再回到五阶段主线，把其余页面补齐。</p><h2 id="动手试试-第一周该做什么" tabindex="-1">动手试试：第一周该做什么 <a class="header-anchor" href="#动手试试-第一周该做什么" aria-label="Permalink to &quot;动手试试：第一周该做什么&quot;">​</a></h2><p>第一周不追求读完本站，只追求建立初步概念并留下笔记。以下按每天 30-60 分钟的节奏安排，时间紧张可以整体拉长：</p><ul><li><strong>第 1-2 天</strong>：读 <a href="/ai/basics">AI 基础概念</a> 和 <a href="/ai/machine-learning">机器学习入门</a>。用自己的话写 5 句话笔记，说明 AI、机器学习、深度学习、模型的关系，以及训练和推理的区别。</li><li><strong>第 3-4 天</strong>：读 <a href="/llm/basics">大模型入门</a>，并打开一个你常用的对话助手做三个小实验：让它解释一个你熟悉的概念，检查有没有错；让它总结一段长文，看它有没有抓住重点；问一个较新的时事问题，观察它是承认不知道还是编造答案。</li><li><strong>第 5 天</strong>：读 <a href="/prompting/basics">Prompt 入门</a>，把六要素（角色、任务、上下文、输出格式、约束、示例）套在一个真实小任务上（例如整理一段笔记），保存你使用的 Prompt 和得到的结果。</li><li><strong>第 6 天</strong>：读 <a href="/tools/common-tools">常用工具</a>，对照你正在用的工具，弄清它属于哪一类：Web 助手、API、本地模型还是绘画界面。</li><li><strong>第 7 天</strong>：翻一遍 <a href="/glossary">术语表</a>，把本周遇到但还没搞懂的词记成一份“待弄清”清单，带着它进入第二阶段。</li></ul><p>一周结束时的产出：</p><ul><li>一页概念笔记：写清 AI、机器学习、深度学习、模型的关系，以及训练和推理的区别。</li><li>三份实验记录：保存当时的输入、输出和你发现的问题。</li><li>一条改进过的 Prompt：对照六要素说明你改了什么、为什么改。</li><li>一份“待弄清”术语清单。</li></ul><p>做实验时注意三点：一次只改一个变量，否则说不清是哪个因素起了作用；保存原始输入和输出，不要凭印象复述；把“模型答错了”也记下来，错误样本最能暴露概念盲区。</p><p>一周只是参考节奏，工作忙可以拉长到两周，重要的是每天留下一小段笔记，而不是赶进度；中断之后，从上次的产出清单接着走即可。完成这些只说明你建立了初步概念，不等于掌握了理论细节，后续页面会逐层展开。</p><h2 id="不同背景读者的路径建议" tabindex="-1">不同背景读者的路径建议 <a class="header-anchor" href="#不同背景读者的路径建议" aria-label="Permalink to &quot;不同背景读者的路径建议&quot;">​</a></h2><p>下表按背景给出主线；无论哪条路线，都建议先跑通最小流程，再逐步增加环节，否则出了问题很难定位：</p><table tabindex="0"><thead><tr><th>读者背景</th><th>建议主线</th><th>可暂时跳过</th><th>阶段目标</th></tr></thead><tbody><tr><td>完全零基础</td><td>阶段一到五基本按顺序读，第一遍允许略读 <a href="/ai/neural-networks">神经网络直觉</a> 的推导部分</td><td>暂无</td><td>建立完整的概念图</td></tr><tr><td>有编程经验</td><td>快速过 <a href="/ai/basics">AI 基础概念</a>，直接进 <a href="/llm/basics">大模型入门</a>、<a href="/llm/inference-decoding">推理与解码</a>、<a href="/llm/training-alignment">训练、微调与对齐</a></td><td><a href="/ai/machine-learning">机器学习入门</a> 的大部分直觉内容</td><td>理解 LLM 的工程行为与成本</td></tr><tr><td>只想用 AI 绘画</td><td><a href="/concepts/base-model">底模是什么</a>、<a href="/concepts/components">AI 绘画由哪些部分组成</a>、<a href="/concepts/how-it-works">基本原理</a>、<a href="/models/ecosystems">常见模型生态</a>、<a href="/lora/basics">LoRA 入门</a></td><td>LLM 理论的大部分页面</td><td>看懂工作流，独立完成文生图</td></tr><tr><td>只想用对话模型</td><td><a href="/llm/basics">大模型入门</a>、<a href="/prompting/basics">Prompt 入门</a>、<a href="/llm/rag-agent">RAG 与 Agent</a>、<a href="/tools/common-tools">常用工具</a></td><td><a href="/ai/neural-networks">神经网络直觉</a> 与 AI 绘画专题</td><td>稳定地把任务交给模型并验证结果</td></tr></tbody></table><p>两条提醒：只想用 AI 绘画的读者也建议至少读一遍 <a href="/ai/basics">AI 基础概念</a> 和 <a href="/prompting/basics">Prompt 入门</a>，绘画工作流同样建立在模型、训练和提示条件这些概念上；表中“跳过”都只是推迟，不是永远不用读。</p><p>如果你不确定自己属于哪一类，先按“完全零基础”的路线走完前两个阶段，再回头决定要不要调整。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><p>这些误区贯穿路线的各个阶段，先在这里集中列出，后面各页还会结合具体场景回到它们：</p><ul><li><strong>“背会提示词模板就能用好 AI”</strong>：Prompt 是任务说明而不是咒语；不理解模型、数据和工具之间的关系，换个任务就失效。</li><li><strong>“演示或训练时的表现就是真实效果”</strong>：真实效果要结合验证数据、测试数据和自己的任务来看。</li><li><strong>“调高 Temperature、Top-p 模型就更聪明”</strong>：采样参数只改变输出的选择方式，不会增加知识或推理能力。</li><li><strong>“回答流畅就说明内容正确”</strong>：流畅和正确是两回事，重要结论需要自行核对来源。</li><li><strong>“接入 RAG 或 Agent 就会自动可靠”</strong>：检索质量、权限控制和失败路径决定实际效果，接入不等于可靠。</li><li><strong>“资料、模型和素材可以随便用”</strong>：数据、模型、素材、API 和平台都可能有许可证与用途限制，公开分发或商用前必须确认。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-为什么本站把-prompt-和工具放在理论之后-而不是放在最前面" tabindex="-1">1. 为什么本站把 Prompt 和工具放在理论之后，而不是放在最前面？ <a class="header-anchor" href="#_1-为什么本站把-prompt-和工具放在理论之后-而不是放在最前面" aria-label="Permalink to &quot;1. 为什么本站把 Prompt 和工具放在理论之后，而不是放在最前面？&quot;">​</a></h3><details><summary>查看答案</summary><p>因为 Prompt 的写法取决于对模型能力边界的理解：不知道 Token、上下文和幻觉这些概念，调 Prompt 很容易变成碰运气。先建立概念，再学技巧，遇到新工具时也能自己判断每个选项在做什么。</p><p>反过来，只背模板时你只知道“这样说有效”，却不知道为什么有效，也无法判断一次失败究竟是 Prompt 的问题，还是任务本身不适合这个模型。</p></details><h3 id="_2-如果你的目标是-ai-绘画-主线是哪几页-为什么仍建议读一遍-ai-基础概念" tabindex="-1">2. 如果你的目标是 AI 绘画，主线是哪几页？为什么仍建议读一遍 AI 基础概念？ <a class="header-anchor" href="#_2-如果你的目标是-ai-绘画-主线是哪几页-为什么仍建议读一遍-ai-基础概念" aria-label="Permalink to &quot;2. 如果你的目标是 AI 绘画，主线是哪几页？为什么仍建议读一遍 AI 基础概念？&quot;">​</a></h3><details><summary>查看答案</summary><p>主线是底模是什么、模型组成、基本原理、常见模型生态和 LoRA 入门。但绘画模型同样要经过训练，同样用 Prompt 表达生成条件，模型、训练、推理这些概念是通用的；读一遍 AI 基础概念，后面页面里的术语就不再陌生。</p><p>绘画工具里的提示词同样是交给模型的生成条件，而不是万能口令——这一点和对话模型完全一致。</p></details><h3 id="_3-第一周结束时-用什么标准判断自己-跟上了" tabindex="-1">3. 第一周结束时，用什么标准判断自己“跟上了”？ <a class="header-anchor" href="#_3-第一周结束时-用什么标准判断自己-跟上了" aria-label="Permalink to &quot;3. 第一周结束时，用什么标准判断自己“跟上了”？&quot;">​</a></h3><details><summary>查看答案</summary><p>不看“读了几页”，看能否合上页面用自己的话复述核心概念之间的关系，并且留下了实际产出：概念笔记、实验记录、改进过的 Prompt 和术语清单。能说清楚自己还不懂什么，也是跟上的标志。</p></details><h2 id="下一步阅读" tabindex="-1">下一步阅读 <a class="header-anchor" href="#下一步阅读" aria-label="Permalink to &quot;下一步阅读&quot;">​</a></h2><ul><li>上一篇：<a href="/">首页</a>：回看本站的定位与整体介绍。</li><li>下一篇：<a href="/ai/basics">AI 基础概念</a>：路线第一站，建立 AI、机器学习、深度学习与模型的概念框架。</li><li>相关阅读：<a href="/glossary">术语表</a>：阅读任何一页时遇到陌生词，都可以回来查。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><p>以下资料供路线走完后的深入阅读，第一周不必全读：</p><ul><li><a href="https://developers.google.com/machine-learning/crash-course" target="_blank" rel="noreferrer">Google：Machine Learning Crash Course</a>：Google 官方机器学习速成课程，对应阶段一。</li><li><a href="https://www.3blue1brown.com/topics/neural-networks" target="_blank" rel="noreferrer">3Blue1Brown：Neural Networks</a>：可视化的神经网络系列视频，辅助建立阶段一的直觉。</li><li><a href="https://huggingface.co/learn/llm-course/chapter1/1" target="_blank" rel="noreferrer">Hugging Face LLM Course</a>：Hugging Face 官方 LLM 课程，对应阶段二。</li><li><a href="https://huggingface.co/docs/diffusers/index" target="_blank" rel="noreferrer">Hugging Face：Diffusers 文档</a>：扩散模型官方文档，对应阶段四的基本原理。</li></ul>',52)])])}const f=e(i,[["render",o]]);export{p as __pageData,f as default};
